<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cetak QR Kamar {{ $room->room_number }}</title><style>body{font-family:Arial,sans-serif;margin:0;color:#1f2937}.sheet{width:148mm;min-height:210mm;margin:0 auto;box-sizing:border-box;padding:20mm;text-align:center;border:1px solid #ddd}.logo{font-size:26px;font-weight:700;letter-spacing:1px}.subtitle{color:#6b7280}.qr{width:95mm;height:95mm;margin:12mm auto 5mm}.room{font-size:32px;font-weight:700;margin:4mm}.note{font-size:14px;line-height:1.6}.url{font-size:9px;color:#9ca3af;word-break:break-all;margin-top:8mm}@media print{.sheet{border:0}.print-button{display:none}}.print-button{margin:20px;padding:10px 18px}</style></head><body><button class="print-button" onclick="window.print()">Cetak</button><main class="sheet"><div class="logo">CANDRA RESORT</div><p class="subtitle">Room Service</p><img class="qr" src="{{ route('receptionist.rooms.qr.image', $room) }}" alt="QR Kamar {{ $room->room_number }}"><div class="room">KAMAR {{ $room->room_number }}</div><p>{{ $room->roomType->name }}</p><p class="note">Pindai QR, lalu masukkan nomor telepon yang didaftarkan saat check-in.<br>Akses hanya aktif selama masa menginap.</p><div class="url">{{ $accessUrl }}</div></main><script>window.addEventListener('load',()=>window.print())</script></body></html>
